### Clean Motor Control Encapsulation Sketch

Here is production-grade motor control code that encapsulates direction logic, clamps speed values with `constrain()`, and executes smooth acceleration and deceleration ramps.

```cpp
// PWM Speed Regulation and Ramp Controller
// Pin 9 is a hardware PWM output connected to L293D Enable 1
const int enablePin = 9; // L293D Pin 1 (1,2EN)
const int in1Pin    = 8; // L293D Pin 2 (1A)
const int in2Pin    = 7; // L293D Pin 7 (2A)

const int MIN_SPEED = 70;  // Stiction threshold (below this motor just hums)
const int MAX_SPEED = 230; // Max continuous cruising speed

void setup() {
  pinMode(enablePin, OUTPUT);
  pinMode(in1Pin, OUTPUT);
  pinMode(in2Pin, OUTPUT);

  stopMotor();
  Serial.begin(9600);
  Serial.println(F("--- PWM Motor Speed Regulation Initialized ---"));
}

void setMotorSpeed(int speed, bool forward) {
  // Set directional legs
  if (forward) {
    digitalWrite(in1Pin, HIGH);
    digitalWrite(in2Pin, LOW);
  } else {
    digitalWrite(in1Pin, LOW);
    digitalWrite(in2Pin, HIGH);
  }
  // Clamp PWM duty cycle to safe 0-255 bounds
  int safePwm = constrain(speed, 0, 255);
  analogWrite(enablePin, safePwm);
}

void stopMotor() {
  digitalWrite(in1Pin, LOW);
  digitalWrite(in2Pin, LOW);
  analogWrite(enablePin, 0);
}

void rampSpeed(int fromSpeed, int toSpeed, bool forward, int stepDelayMs) {
  int step = (fromSpeed < toSpeed) ? 5 : -5;
  for (int s = fromSpeed; (step > 0) ? (s <= toSpeed) : (s >= toSpeed); s += step) {
    setMotorSpeed(s, forward);
    delay(stepDelayMs);
  }
}

void loop() {
  Serial.println(F("RAMPING UP: Accelerating forward from MIN to MAX speed..."));
  rampSpeed(MIN_SPEED, MAX_SPEED, true, 30); // 30ms per 5 PWM units
  delay(1500); // Cruise at high speed

  Serial.println(F("RAMPING DOWN: Smoothly decelerating to stop..."));
  rampSpeed(MAX_SPEED, 0, true, 20);
  stopMotor();
  delay(1000);

  Serial.println(F("RAMPING UP: Accelerating reverse..."));
  rampSpeed(MIN_SPEED, MAX_SPEED, false, 30);
  delay(1500);

  Serial.println(F("RAMPING DOWN: Decelerating reverse to stop..."));
  rampSpeed(MAX_SPEED, 0, false, 20);
  stopMotor();
  delay(2000);
}
```

### Code Breakdown:
- `analogWrite(enablePin, safePwm)`: Generates a 490 Hz square wave on Pin 9 that gates the L293D Channel 1 outputs at the commanded duty cycle.
- `constrain(speed, 0, 255)`: Prevents numerical overflows from corrupting the PWM register.
- `MIN_SPEED = 70`: Skips the non-rotating friction deadband directly to useful mechanical rotation.
- `rampSpeed()`: Steps the PWM value in small increments of 5 units every 20–30 ms, eliminating electrical current spikes and mechanical gear shocks.
